package be.winnetrie.mod.simpleserverutilities.client.gui;
import java.util.Map;import com.google.gson.Gson;import com.google.gson.GsonBuilder;import com.google.gson.JsonArray;import com.google.gson.JsonObject;import be.winnetrie.mod.simpleserverutilities.network.PlayerInventoryOpenPayload;import be.winnetrie.mod.simpleserverutilities.network.PlayerManagementActionPayload;import be.winnetrie.mod.simpleserverutilities.network.PlayerManagementDataPayload;import net.minecraft.client.gui.GuiGraphicsExtractor;import net.minecraft.client.gui.components.Button;import net.minecraft.client.gui.components.EditBox;import net.minecraft.client.gui.screens.Screen;import net.minecraft.network.chat.Component;import net.neoforged.neoforge.client.network.ClientPacketDistributor;
/** Compact player moderation, jail, whitelist, history and inventory hub. */
public final class PlayerManagementScreen extends Screen{private static final Gson GSON=new GsonBuilder().create();private static final int W=680,H=400,PANEL=0xF0161D25,BORDER=0xFF586978,TEXT=0xFFF3F5F7,MUTED=0xFFAAB5BE,GOOD=0xFF83E39A,ERROR=0xFFFF8585;private PlayerManagementDataPayload data;private final Screen parent;private JsonObject json;private Tab tab=Tab.ACTIONS;private long request=1;private String reason="";private EditBox duration,warning,buyout,region,requirements,tools,lookback,whitelistEntry;
 public PlayerManagementScreen(PlayerManagementDataPayload d,Screen parent){super(Component.literal("Manage Player"));this.data=d;this.parent=parent;parse();}private void parse(){try{json=GSON.fromJson(data.json(),JsonObject.class);}catch(Exception e){json=new JsonObject();}if(json==null)json=new JsonObject();}
 public void accept(PlayerManagementDataPayload d){this.data=d;parse();rebuildWidgets();}
 @Override protected void init(){int x=left(),y=top();for(Tab t:Tab.values()){Button b=addRenderableWidget(Button.builder(Component.literal(t.label),z->{tab=t;rebuildWidgets();}).bounds(x+16+t.ordinal()*105,y+42,99,20).build());b.active=t!=tab;}addRenderableWidget(Button.builder(Component.literal("Close"),b->onClose()).bounds(x+W-88,y+H-28,72,20).build());switch(tab){case ACTIONS->actions(x,y);case JAIL->jail(x,y);case WHITELIST->whitelist(x,y);case HISTORY->history(x,y);case INVENTORY->inventory(x,y);}}
 private void actions(int x,int y){addRenderableWidget(Button.builder(Component.literal("Edit reason (rich text)"),b->minecraft.setScreenAndShow(new RichTextValueEditorScreen(this,"Moderation reason","Formatting is retained for warnings, kicks and bans.",reason,v->reason=v))).bounds(x+18,y+82,190,20).build());warning=box(x+218,y+82,70,Integer.toString(intJson("defaultWarningSeconds",8)),3,"Seconds");addRenderableWidget(Button.builder(Component.literal("Warning"),b->send("warn")).bounds(x+296,y+82,92,20).build());addRenderableWidget(Button.builder(Component.literal("Kick"),b->send("kick")).bounds(x+396,y+82,80,20).build());duration=box(x+18,y+126,116,"3600",12,"Ban seconds");addRenderableWidget(Button.builder(Component.literal("Temporary ban"),b->send("ban_temp")).bounds(x+142,y+126,130,20).build());addRenderableWidget(Button.builder(Component.literal("Permanent ban"),b->send("ban_permanent")).bounds(x+280,y+126,130,20).build());addRenderableWidget(Button.builder(Component.literal("Unban"),b->send("unban")).bounds(x+418,y+126,86,20).build());addRenderableWidget(Button.builder(Component.literal(bool("frozen")?"Unfreeze":"Freeze"),b->send(bool("frozen")?"unfreeze":"freeze")).bounds(x+18,y+172,110,20).build());}
 private void jail(int x,int y){JsonObject j=json.has("jail")&&json.get("jail").isJsonObject()?json.getAsJsonObject("jail"):new JsonObject();boolean active=j.has("active")&&j.get("active").getAsBoolean();Button configure=addRenderableWidget(Button.builder(Component.literal("Configure punishment"),b->minecraft.setScreenAndShow(new JailPunishmentScreen(this,data))).bounds(x+18,y+82,168,22).build());configure.active=!active;Button release=addRenderableWidget(Button.builder(Component.literal("Release prisoner"),b->send("unjail")).bounds(x+196,y+82,138,22).build());release.active=active;Button tp=addRenderableWidget(Button.builder(Component.literal("Teleport to prisoner"),b->send("jail_tp_to")).bounds(x+344,y+82,148,22).build());tp.active=active&&bool("online");addRenderableWidget(Button.builder(Component.literal("Jail administration"),b->ClientPacketDistributor.sendToServer(new be.winnetrie.mod.simpleserverutilities.network.JailAdminRequestPayload("",request++))).bounds(x+502,y+82,154,22).build());}
 private void whitelist(int x,int y){boolean on=bool("whitelistEnabled");addRenderableWidget(Button.builder(Component.literal("Whitelist: "+(on?"ON":"OFF")),b->send(on?"whitelist_disable":"whitelist_enable")).bounds(x+18,y+82,150,20).build());whitelistEntry=box(x+18,y+126,280,"",64,"Player name or UUID");addRenderableWidget(Button.builder(Component.literal("Add"),b->sendWhitelist("whitelist_add")).bounds(x+306,y+126,70,20).build());addRenderableWidget(Button.builder(Component.literal("Remove"),b->sendWhitelist("whitelist_remove")).bounds(x+384,y+126,82,20).build());}
 private void history(int x,int y){}
 private void inventory(int x,int y){addRenderableWidget(Button.builder(Component.literal("Open inventory & armor"),b->openInventory("inventory")).bounds(x+18,y+82,190,22).build());addRenderableWidget(Button.builder(Component.literal("Open ender chest"),b->openInventory("ender")).bounds(x+218,y+82,160,22).build());}
 private EditBox box(int x,int y,int w,String v,int max,String hint){EditBox e=new EditBox(font,x,y,w,20,Component.literal(hint));e.setValue(v);e.setMaxLength(max);addRenderableWidget(e);return e;}private void openInventory(String mode){ClientPacketDistributor.sendToServer(new PlayerInventoryOpenPayload(data.target(),mode,request++));}
 private void sendWhitelist(String action){String entry=whitelistEntry==null?"":whitelistEntry.getValue();ClientPacketDistributor.sendToServer(new PlayerManagementActionPayload(action,data.target(),reason,longValue(duration),intValue(warning,8),longValue(buyout),entry,requirements==null?"{}":requirements.getValue(),tools==null?"[]":tools.getValue(),intValue(lookback,30),"",0L,request++));}
 private void send(String action){ClientPacketDistributor.sendToServer(payload(action,data.target()));}
 private PlayerManagementActionPayload payload(String action,String target){return new PlayerManagementActionPayload(action,target,reason,longValue(duration),intValue(warning,8),longValue(buyout),region==null?"":region.getValue(),requirements==null?"{}":requirements.getValue(),tools==null?"[]":tools.getValue(),intValue(lookback,30),"",0L,request++);}
 private static long longValue(EditBox b){try{return b==null?0L:Long.parseLong(b.getValue().trim());}catch(Exception e){return 0L;}}private static int intValue(EditBox b,int f){try{return b==null?f:Integer.parseInt(b.getValue().trim());}catch(Exception e){return f;}}private int intJson(String k,int f){try{return json.has(k)?json.get(k).getAsInt():f;}catch(Exception e){return f;}}private boolean bool(String k){return json.has(k)&&json.get(k).getAsBoolean();}
 @Override public void extractRenderState(GuiGraphicsExtractor g,int mx,int my,float pt){int x=left(),y=top();SsuGuiScale.fullscreenDim(g, this, 0xA5000000);g.fill(x,y,x+W,y+H,PANEL);g.outline(x,y,W,H,BORDER);g.text(font,"Manage player — "+str("name",data.target()),x+16,y+15,TEXT,true);g.text(font,str("uuid",""),x+260,y+15,MUTED,false);if(tab==Tab.ACTIONS){g.text(font,"Online: "+bool("online")+" • Banned: "+bool("banned")+" • Frozen: "+bool("frozen"),x+18,y+218,MUTED,false);}else if(tab==Tab.JAIL){JsonObject j=json.has("jail")&&json.get("jail").isJsonObject()?json.getAsJsonObject("jail"):new JsonObject();boolean active=j.has("active")&&j.get("active").getAsBoolean();g.text(font,"Active prisoner: "+(active?"YES":"NO"),x+18,y+130,active?GOOD:MUTED,false);if(active){String path=j.has("selectedPath")?j.get("selectedPath").getAsString():"-";g.text(font,"Jail: "+(j.has("jailId")?j.get("jailId").getAsString():"legacy")+" • Mode: "+(j.has("sentenceMode")?j.get("sentenceMode").getAsString():"-")+" • Selected: "+path,x+18,y+154,TEXT,false);long deadline=j.has("taskDeadlineAt")?j.get("taskDeadlineAt").getAsLong():0L,releaseAt=j.has("releaseAt")?j.get("releaseAt").getAsLong():0L,choiceAt=j.has("choiceExpiresAt")?j.get("choiceExpiresAt").getAsLong():0L;String timing="TIME".equals(path)?"Release: "+when(releaseAt):("PENDING".equals(path)?"Choice locks: "+when(choiceAt):"Task deadline: "+when(deadline));g.text(font,timing,x+18,y+178,MUTED,false);if(j.has("reason"))g.text(font,"Reason: "+trim(strip(j.get("reason").getAsString()),82),x+18,y+200,MUTED,false);}g.text(font,"Jail facilities are managed separately. Every Jail must fit entirely inside an existing Region.",x+18,y+234,MUTED,false);g.text(font,"Mines remain independent and may be nested inside a Jail without becoming part of the punishment system.",x+18,y+256,MUTED,false);}else if(tab==Tab.WHITELIST){JsonArray a=json.has("whitelist")?json.getAsJsonArray("whitelist"):new JsonArray();g.text(font,"Entries: "+a.size(),x+18,y+170,MUTED,false);for(int i=0;i<Math.min(12,a.size());i++)g.text(font,a.get(i).getAsString(),x+18+(i/6)*250,y+190+(i%6)*16,TEXT,false);}else if(tab==Tab.HISTORY){JsonArray a=json.has("history")?json.getAsJsonArray("history"):new JsonArray();int start=Math.max(0,a.size()-16);for(int i=start;i<a.size();i++){JsonObject h=a.get(i).getAsJsonObject();String line=(h.has("type")?h.get("type").getAsString():"event")+" • "+(h.has("actorName")?h.get("actorName").getAsString():"Server")+" • "+(h.has("reason")?strip(h.get("reason").getAsString()):"");g.text(font,trim(line,90),x+18,y+82+(i-start)*17,TEXT,false);}JsonArray names=json.has("knownNames")?json.getAsJsonArray("knownNames"):new JsonArray();g.text(font,"Known names: "+names,x+18,y+360,MUTED,false);}else g.text(font,"Online changes apply when the editor closes. Offline snapshots apply on next login.",x+18,y+124,MUTED,false);if(!data.notice().isBlank())g.text(font,trim(data.notice(),90),x+18,y+H-25,data.error()?ERROR:GOOD,false);super.extractRenderState(g,mx,my,pt);}
 private String str(String k,String f){return json.has(k)?json.get(k).getAsString():f;}private static String when(long epoch){if(epoch<=0L)return"-";return java.time.format.DateTimeFormatter.ofPattern("dd/MM/yyyy HH:mm").withZone(java.time.ZoneId.systemDefault()).format(java.time.Instant.ofEpochMilli(epoch));}private static String strip(String s){return s==null?"":s.replaceAll("§[0-9A-FK-ORa-fk-or]","").replace('\n',' ');}private static String trim(String s,int m){return s.length()<=m?s:s.substring(0,m-1)+"…";}@Override public void onClose(){if(minecraft!=null)minecraft.setScreenAndShow(parent);}@Override public boolean isPauseScreen(){return false;}private int left(){return(width-W)/2;}private int top(){return(height-H)/2;}private enum Tab{ACTIONS("Actions"),JAIL("Jail"),WHITELIST("Whitelist"),HISTORY("History"),INVENTORY("Inventory");final String label;Tab(String l){label=l;}}}
